import Cocoa
import Security
import CryptoKit

struct RDPCertificateSummary {
 let host:String,subject:String,fingerprint:String;let trusted:Bool;let issue:String?
 static func certificates(_ pem:String)throws->[SecCertificate] {guard !pem.isEmpty,pem.utf8.count<=262144,!pem.contains("\0") else{throw SFTPError.message("RDP 证书链为空或超过限制")};let begin="-----BEGIN CERTIFICATE-----",end="-----END CERTIFICATE-----";var rest=pem[...],result=[SecCertificate]();while !rest.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty {guard result.count<16,let first=rest.range(of:begin),rest[..<first.lowerBound].trimmingCharacters(in:.whitespacesAndNewlines).isEmpty,let last=rest[first.upperBound...].range(of:end) else{throw SFTPError.message("RDP 证书链格式无效")};let body=rest[first.upperBound..<last.lowerBound].filter{!$0.isWhitespace};guard body.utf8.allSatisfy({(65...90).contains($0)||(97...122).contains($0)||(48...57).contains($0)||[43,47,61].contains($0)}),let data=Data(base64Encoded:body),!data.isEmpty,data.count<=65536,let certificate=SecCertificateCreateWithData(nil,data as CFData) else{throw SFTPError.message("RDP 证书无法解析")};result.append(certificate);rest=rest[last.upperBound...]};guard !result.isEmpty else{throw SFTPError.message("RDP 没有提供证书")};return result}
 static func evaluate(pem:String,host:String,anchors:[SecCertificate]?=nil,verificationDate:Date?=nil)throws->RDPCertificateSummary {let chain=try certificates(pem);let policy=SecPolicyCreateSSL(true,host as CFString);var trust:SecTrust?;guard SecTrustCreateWithCertificates(chain as CFArray,policy,&trust)==errSecSuccess,let evaluated=trust else{throw SFTPError.message("无法建立 RDP 证书验证")};SecTrustSetNetworkFetchAllowed(evaluated,false);if let date=verificationDate{SecTrustSetVerifyDate(evaluated,date as CFDate)};if let anchors=anchors{guard SecTrustSetAnchorCertificates(evaluated,anchors as CFArray)==errSecSuccess,SecTrustSetAnchorCertificatesOnly(evaluated,true)==errSecSuccess else{throw SFTPError.message("无法配置测试证书锚点")}};var error:CFError?;let trusted=SecTrustEvaluateWithError(evaluated,&error);let data=SecCertificateCopyData(chain[0]) as Data;let digest=SHA256.hash(data:data).map{String(format:"%02X",$0)}.joined(separator:":");let raw=(SecCertificateCopySubjectSummary(chain[0]) as String?) ?? "无主题名称";let subject=String(decoding:Data(raw.utf8.prefix(512)),as:UTF8.self).filter{!$0.unicodeScalars.contains(where:{$0.value<32||$0.value==127})};return RDPCertificateSummary(host:host,subject:subject,fingerprint:digest,trusted:trusted,issue:trusted ? nil : (error as Error?)?.localizedDescription ?? "系统未能验证此证书链。")}
}
